// Video upload server: ONE file = server + upload page + gallery widget (needs only package.json).
// Runs on Railway (or any Node host).
// Storage: local disk (attach a Railway Volume) OR Cloudflare R2 / S3 (set the S3_* variables).
const express = require("express");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const { Transform } = require("stream");
const { pipeline } = require("stream/promises");

const env = (k, d = "") => process.env[k] || d;
const PORT = Number(env("PORT", "3000"));
const SITE_NAME = env("SITE_NAME", "STREAM");
const API_KEY = env("UPLOAD_KEY", "v8ut8EKZUMihABENQqYqHyl5");
const FIXED_ORIGIN = env("BASE_URL").replace(/\/$/, "");

const DATA_DIR = path.resolve(env("DATA_DIR") || env("RAILWAY_VOLUME_MOUNT_PATH") || path.join(process.cwd(), "data"));
const FILES_DIR = path.join(DATA_DIR, "files");
const TMP_DIR = path.join(DATA_DIR, "tmp");
const DB_FILE = path.join(DATA_DIR, "videos.json");
[FILES_DIR, TMP_DIR].forEach((d) => fs.mkdirSync(d, { recursive: true }));

// ---------- languages ----------
const LANGS = env("LANGS", "en:English,fr:Français,es:Español")
  .split(",")
  .map((s) => {
    const [code, ...rest] = s.trim().split(":");
    return { code: code.trim().toLowerCase(), label: (rest.join(":") || code).trim() };
  })
  .filter((l) => /^[a-z]{2,3}(-[a-z]{2,4})?$/.test(l.code));
if (!LANGS.length) { console.error("LANGS is empty or invalid."); process.exit(1); }
const isLang = (c) => LANGS.some((l) => l.code === c);

// ---------- storage mode ----------
const BUCKET = env("S3_BUCKET");
const PUBLIC_BASE = env("PUBLIC_BASE_URL").replace(/\/$/, "");
const R2 = Boolean(env("S3_ENDPOINT") && env("S3_ACCESS_KEY_ID") && env("S3_SECRET_ACCESS_KEY") && BUCKET && PUBLIC_BASE);
let S3, presign, client;
if (R2) {
  S3 = require("@aws-sdk/client-s3");
  presign = require("@aws-sdk/s3-request-presigner").getSignedUrl;
  client = new S3.S3Client({
    region: env("S3_REGION", "auto"),
    endpoint: env("S3_ENDPOINT"),
    forcePathStyle: true,
    credentials: { accessKeyId: env("S3_ACCESS_KEY_ID"), secretAccessKey: env("S3_SECRET_ACCESS_KEY") },
    requestChecksumCalculation: "WHEN_REQUIRED",
    responseChecksumValidation: "WHEN_REQUIRED",
  });
}

const rand = (n) => crypto.randomBytes(n).toString("hex");
const SAFE_KEY = /^[A-Za-z0-9][A-Za-z0-9._-]{2,200}$/;
const MPU_KEY = /^[a-f0-9]{16}-video-[a-z0-9-]+\.[a-z0-9]+$/;

const TYPES = {
  ".mp4": "video/mp4", ".m4v": "video/x-m4v", ".mov": "video/quicktime", ".webm": "video/webm",
  ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".png": "image/png", ".webp": "image/webp",
  ".vtt": "text/vtt; charset=utf-8",
};
const MAX_FILE = 4 * 1024 ** 3;            // single-request files (posters, subtitles, videos under 100 MB)
const MAX_VIDEO = Math.round(Number(env("MAX_VIDEO_GB", "2")) * 1024 ** 3); // largest allowed video file (default 2 GB)
const fmtGB = (n) => `${+(n / 1024 ** 3).toFixed(2)} GB`;
const MAX_SUB = 5 * 1024 ** 2;
const R2_PART = 64 * 1024 ** 2;
const LOCAL_PART = 16 * 1024 ** 2;

// ---------- database (kept in memory, saved to disk or to the bucket) ----------
const DB_KEY = "_db/videos.json";
let cache = [];
async function loadDb() {
  if (R2) {
    try {
      const r = await client.send(new S3.GetObjectCommand({ Bucket: BUCKET, Key: DB_KEY }));
      cache = JSON.parse(await r.Body.transformToString());
    } catch (e) {
      if (e.name === "NoSuchKey" || (e.$metadata && e.$metadata.httpStatusCode === 404)) cache = []; else throw e;
    }
  } else {
    try { cache = JSON.parse(fs.readFileSync(DB_FILE, "utf8")); } catch (e) { cache = []; }
  }
}
async function persistDb() {
  const body = JSON.stringify(cache, null, 2);
  if (R2) await client.send(new S3.PutObjectCommand({ Bucket: BUCKET, Key: DB_KEY, Body: body, ContentType: "application/json" }));
  else { fs.writeFileSync(DB_FILE + ".tmp", body); fs.renameSync(DB_FILE + ".tmp", DB_FILE); }
}
let queue = Promise.resolve();
function mutate(fn) { // one change at a time
  const run = queue.catch(() => {}).then(async () => { const out = fn(cache); await persistDb(); return out; });
  queue = run;
  return run;
}
const httpErr = (status, message) => Object.assign(new Error(message), { status });

// ---------- helpers ----------
const app = express();
app.set("trust proxy", true);
const origin = (req) => FIXED_ORIGIN || `${req.protocol}://${req.get("host")}`;
const filesBase = (req) => (R2 ? PUBLIC_BASE : origin(req) + "/files");
const esc = (s) => String(s).replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));

function toApi(row, req) {
  const base = filesBase(req), versions = {};
  for (const [c, v] of Object.entries(row.versions)) {
    versions[c] = {
      video: `${base}/${v.video}`,
      poster: v.poster ? `${base}/${v.poster}` : null,
      subs: (v.subs || []).map((s) => ({ lang: s.lang, url: `${base}/${s.key}` })),
    };
  }
  const rowPosters = {};
  for (const [c, k] of Object.entries(row.rowPosters || {})) rowPosters[c] = `${base}/${k}`;
  return { id: row.id, createdAt: row.createdAt, group: row.group || "", titles: row.titles, categories: row.categories, rowPosters, versions, embed: `${origin(req)}/embed/${row.id}` };
}
// a file is only deleted when no entry uses it any more (a series poster is shared by many videos)
function isUsed(k) {
  return cache.some((r) => Object.values(r.rowPosters || {}).includes(k) ||
    Object.values(r.versions).some((v) => v.video === k || v.poster === k || (v.subs || []).some((s) => s.key === k)));
}
function removeKeys(keys) {
  [...new Set(keys)].filter((k) => k && SAFE_KEY.test(k) && !isUsed(k)).forEach((k) => {
    if (R2) client.send(new S3.DeleteObjectCommand({ Bucket: BUCKET, Key: k })).catch(() => {});
    else fs.rm(path.join(FILES_DIR, k), { force: true }, () => {});
  });
}
function freeBytes() {
  try { const s = fs.statfsSync(DATA_DIR); return s.bavail * s.bsize; } catch (e) { return Infinity; }
}
function auth(req, res, next) {
  const a = Buffer.from(String(req.get("x-api-key") || "")), b = Buffer.from(API_KEY);
  if (a.length === b.length && crypto.timingSafeEqual(a, b)) return next();
  setTimeout(() => res.status(401).json({ error: "Wrong upload key." }), 400);
}
async function writeStream(req, file, { start = 0, flags = "w", maxBytes }) {
  let n = 0;
  const counter = new Transform({
    transform(chunk, _enc, cb) { n += chunk.length; if (n > maxBytes) return cb(new Error("Upload is larger than expected.")); cb(null, chunk); },
  });
  await pipeline(req, counter, fs.createWriteStream(file, { flags, start }));
  return n;
}

// upload sessions for local-disk mode
const tokens = new Map();    // single-file upload tokens
const sessions = new Map();  // multipart sessions
setInterval(() => {
  const now = Date.now();
  for (const [k, t] of tokens) if (t.exp < now) tokens.delete(k);
  for (const [k, s] of sessions) if (s.exp < now) { fs.rm(s.tmp, { force: true }, () => {}); sessions.delete(k); }
  for (const f of fs.readdirSync(TMP_DIR)) {
    const p = path.join(TMP_DIR, f);
    try { if (now - fs.statSync(p).mtimeMs > 36 * 3600e3) fs.rmSync(p, { force: true }); } catch (e) {}
  }
}, 3600e3).unref();

// ---------- middleware & static ----------
app.use(["/api", "/files", "/widget.js"], (req, res, next) => { res.set("Access-Control-Allow-Origin", "*"); next(); });
app.use("/api", express.json({ limit: "2mb" }));
app.get("/health", (req, res) => res.send("ok"));
app.use("/files", express.static(FILES_DIR, { maxAge: "7d", index: false, dotfiles: "ignore" }));
// the pages are embedded at the bottom of this file (see PAGES)
const page = (type, key) => (req, res) => res.type(type).send(PAGES[key]);
app.get("/", (req, res) => res.redirect("/admin"));
app.get(["/admin", "/admin.html"], page("html", "admin"));
app.get("/widget.js", page("js", "widget"));

// ---------- API ----------
app.get("/api/videos", (req, res) => {
  res.set("Cache-Control", "no-store");
  res.json({ site: SITE_NAME, languages: LANGS, limits: { maxVideoBytes: MAX_VIDEO }, videos: cache.map((r) => toApi(r, req)) });
});

app.delete("/api/videos/:id", auth, async (req, res) => {
  try {
    const row = await mutate((rows) => {
      const i = rows.findIndex((r) => r.id === req.params.id);
      if (i < 0) throw httpErr(404, "Not found");
      return rows.splice(i, 1)[0];
    });
    removeKeys([...Object.values(row.versions).flatMap((v) => [v.video, v.poster, ...((v.subs || []).map((s) => s.key))]), ...Object.values(row.rowPosters || {})]);
    res.sendStatus(204);
  } catch (e) { res.status(e.status || 500).json({ error: e.message }); }
});

function classify(f) {
  const field = String(f.field);
  const m = /^(video|poster)_([a-z0-9-]+)$/.exec(field);
  const sm = /^sub_([a-z0-9-]+)_([a-z0-9-]+)$/.exec(field);
  const ext = ((/\.[a-z0-9]+$/i.exec(String(f.name)) || [""])[0]).toLowerCase();
  const type = TYPES[ext], size = Number(f.size);
  if (m && isLang(m[2])) {
    if (!type || !type.startsWith(m[1] === "video" ? "video/" : "image/")) return { error: `File type not allowed for ${field}` };
    const cap = m[1] === "video" ? MAX_VIDEO : MAX_FILE;
    if (!(size > 0 && size <= cap)) return { error: `File too large (${fmtGB(cap)} max per file).` };
    return { field, type, size, name: `${m[1]}-${m[2]}${ext}` };
  }
  if (sm && isLang(sm[1]) && isLang(sm[2])) {
    if (ext !== ".vtt") return { error: "Subtitles must be .vtt files." };
    if (!(size > 0 && size <= MAX_SUB)) return { error: "Subtitle file too large (5 MB max)." };
    return { field, type, size, name: `sub-${sm[1]}-${sm[2]}.vtt` };
  }
  return { error: `Unknown field ${field}` };
}

// 1) small files: returns an upload URL per file
app.post("/api/sign", auth, async (req, res) => {
  const files = req.body && req.body.files;
  if (!Array.isArray(files) || !files.length || files.length > 12) return res.status(400).json({ error: "Bad request." });
  try {
    const base = filesBase(req), out = [];
    for (const f of files) {
      const spec = classify(f);
      if (spec.error) return res.status(400).json({ error: spec.error });
      if (!R2 && spec.size > freeBytes() * 0.98) return res.status(507).json({ error: "Not enough free disk space on the server volume." });
      const Key = `${rand(8)}-${spec.name}`;
      let uploadUrl;
      if (R2) uploadUrl = await presign(client, new S3.PutObjectCommand({ Bucket: BUCKET, Key, ContentType: spec.type }), { expiresIn: 6 * 3600 });
      else {
        const token = rand(24);
        tokens.set(token, { key: Key, max: spec.size, exp: Date.now() + 6 * 3600e3 });
        uploadUrl = `${origin(req)}/up/file/${token}`;
      }
      out.push({ field: spec.field, uploadUrl, contentType: spec.type, publicUrl: `${base}/${Key}` });
    }
    res.json({ uploads: out });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// 2) big videos: multipart (start / complete / abort)
app.post("/api/mpu/:action", auth, async (req, res) => {
  const b = req.body || {}, action = req.params.action;
  try {
    if (action === "start") {
      const m = /^video_([a-z0-9-]+)$/.exec(String(b.field));
      if (!m || !isLang(m[1])) return res.status(400).json({ error: "Unknown language field." });
      const ext = ((/\.[a-z0-9]+$/i.exec(String(b.name)) || [""])[0]).toLowerCase();
      const type = TYPES[ext];
      if (!type || !type.startsWith("video/")) return res.status(400).json({ error: "Video type not allowed (use mp4, m4v, mov or webm)." });
      const size = Number(b.size);
      if (!(size > 0 && size <= MAX_VIDEO)) return res.status(400).json({ error: `File too large (${fmtGB(MAX_VIDEO)} max per file).` });
      const Key = `${rand(8)}-video-${m[1]}${ext}`;
      const base = filesBase(req);

      if (R2) {
        const { UploadId } = await client.send(new S3.CreateMultipartUploadCommand({ Bucket: BUCKET, Key, ContentType: type }));
        const count = Math.ceil(size / R2_PART);
        const parts = await Promise.all(Array.from({ length: count }, async (_, i) => ({
          n: i + 1,
          url: await presign(client, new S3.UploadPartCommand({ Bucket: BUCKET, Key, UploadId, PartNumber: i + 1 }), { expiresIn: 24 * 3600 }),
        })));
        return res.json({ key: Key, uploadId: UploadId, partSize: R2_PART, parts, publicUrl: `${base}/${Key}` });
      }

      if (size > freeBytes() * 0.98) return res.status(507).json({ error: "Not enough free disk space on the server volume." });
      const uploadId = rand(24), tmp = path.join(TMP_DIR, uploadId + ".mp");
      fs.closeSync(fs.openSync(tmp, "w"));
      const count = Math.ceil(size / LOCAL_PART);
      sessions.set(uploadId, { key: Key, tmp, size, count, partSize: LOCAL_PART, received: new Set(), exp: Date.now() + 24 * 3600e3 });
      const parts = Array.from({ length: count }, (_, i) => ({ n: i + 1, url: `${origin(req)}/up/part/${uploadId}/${i + 1}` }));
      return res.json({ key: Key, uploadId, partSize: LOCAL_PART, parts, publicUrl: `${base}/${Key}` });
    }

    if (!MPU_KEY.test(String(b.key)) || !b.uploadId) return res.status(400).json({ error: "Bad request." });

    if (action === "complete") {
      if (R2) {
        if (!Array.isArray(b.parts) || !b.parts.length) return res.status(400).json({ error: "No parts." });
        const Parts = b.parts.map((p) => ({ PartNumber: Number(p.PartNumber), ETag: String(p.ETag) })).sort((x, y) => x.PartNumber - y.PartNumber);
        await client.send(new S3.CompleteMultipartUploadCommand({ Bucket: BUCKET, Key: b.key, UploadId: b.uploadId, MultipartUpload: { Parts } }));
      } else {
        const s = sessions.get(b.uploadId);
        if (!s || s.key !== b.key) return res.status(404).json({ error: "Upload session not found. Start the upload again." });
        if (s.received.size !== s.count) return res.status(400).json({ error: "Some parts are missing." });
        if (fs.statSync(s.tmp).size !== s.size) return res.status(400).json({ error: "File size mismatch." });
        fs.renameSync(s.tmp, path.join(FILES_DIR, s.key));
        sessions.delete(b.uploadId);
      }
      return res.json({ publicUrl: `${filesBase(req)}/${b.key}` });
    }

    if (action === "abort") {
      if (R2) await client.send(new S3.AbortMultipartUploadCommand({ Bucket: BUCKET, Key: b.key, UploadId: b.uploadId })).catch(() => {});
      else { const s = sessions.get(b.uploadId); if (s) { fs.rm(s.tmp, { force: true }, () => {}); sessions.delete(b.uploadId); } }
      return res.json({ ok: true });
    }
    res.status(404).json({ error: "Unknown action." });
  } catch (e) { res.status(500).json({ error: e.message }); }
});

// local-disk upload endpoints (the URLs handed out above)
app.put("/up/file/:token", async (req, res) => {
  const t = tokens.get(req.params.token);
  if (!t || t.exp < Date.now()) return res.sendStatus(404);
  const tmp = path.join(TMP_DIR, t.key + ".part");
  try {
    const n = await writeStream(req, tmp, { maxBytes: t.max });
    if (!n) throw new Error("Empty upload.");
    fs.renameSync(tmp, path.join(FILES_DIR, t.key));
    tokens.delete(req.params.token);
    res.sendStatus(200);
  } catch (e) { fs.rm(tmp, { force: true }, () => {}); if (!res.headersSent) res.status(400).json({ error: e.message }); }
});
app.put("/up/part/:id/:n", async (req, res) => {
  const s = sessions.get(req.params.id), n = Number(req.params.n);
  if (!s || !(n >= 1 && n <= s.count)) return res.sendStatus(404);
  const offset = (n - 1) * s.partSize, expected = n === s.count ? s.size - offset : s.partSize;
  try {
    const written = await writeStream(req, s.tmp, { start: offset, flags: "r+", maxBytes: expected });
    if (written !== expected) throw new Error("Wrong part size.");
    s.received.add(n);
    res.set("ETag", `"${n}"`).sendStatus(200);
  } catch (e) { if (!res.headersSent) res.status(400).json({ error: e.message }); }
});

// 3) save an entry (new, or add/replace versions and subtitles on an existing one)
const clean = (v, n) => (typeof v === "string" ? v.trim().slice(0, n) : "");
app.post("/api/save", auth, async (req, res) => {
  const b = req.body || {}, base = filesBase(req);
  const toKey = (u) => {
    if (typeof u !== "string" || !u.startsWith(base + "/")) return null;
    const k = u.slice(base.length + 1);
    if (!SAFE_KEY.test(k)) return null;
    if (!R2 && !fs.existsSync(path.join(FILES_DIR, k))) return null;
    return k;
  };
  try {
    const out = await mutate((rows) => {
      const existing = b.id ? rows.find((r) => r.id === b.id) : null;
      if (b.id && !existing) throw httpErr(404, "Entry not found.");
      const row = existing || { id: rand(6), createdAt: new Date().toISOString(), group: "", titles: {}, categories: {}, rowPosters: {}, versions: {} };
      if (!row.rowPosters) row.rowPosters = {};
      if (!row.group && b.group) row.group = clean(b.group, 100);
      const del = [];
      for (const l of LANGS) {
        const nv = (b.versions && b.versions[l.code]) || {};
        const old = row.versions[l.code];
        const video = toKey(nv.video), poster = toKey(nv.poster);
        if (video) {
          if (old) del.push(old.video, old.poster);
          row.versions[l.code] = { video, poster: poster || null, subs: (old && old.subs) || [] };
        } else if (old && poster) {
          del.push(old.poster); old.poster = poster;
        }
        const cur = row.versions[l.code];
        if (cur && Array.isArray(nv.subs)) {
          cur.subs = cur.subs || [];
          for (const s of nv.subs) {
            const k = s && toKey(s.url);
            if (!k || !isLang(s.lang)) continue;
            const prev = cur.subs.find((t) => t.lang === s.lang);
            if (prev) { del.push(prev.key); prev.key = k; } else cur.subs.push({ lang: s.lang, key: k });
          }
        }
        const rp = toKey(nv.rowPoster);
        if (rp) { if (row.rowPosters[l.code] && row.rowPosters[l.code] !== rp) del.push(row.rowPosters[l.code]); row.rowPosters[l.code] = rp; }
        const t = clean(b.titles && b.titles[l.code], 200), c = clean(b.categories && b.categories[l.code], 80);
        if (t) row.titles[l.code] = t;
        if (c) row.categories[l.code] = c;
      }
      if (!Object.keys(row.versions).length) throw httpErr(400, "Upload at least one video.");
      if (!Object.keys(row.titles).length) row.titles[Object.keys(row.versions)[0]] = "Untitled";
      if (!existing) rows.unshift(row);
      return { row, del };
    });
    removeKeys(out.del);
    res.json(toApi(out.row, req));
  } catch (e) { res.status(e.status || 500).json({ error: e.message }); }
});

// ---------- single-video player page (for <iframe>) ----------
app.get("/embed/:id", (req, res) => {
  const found = cache.find((r) => r.id === req.params.id);
  if (!found) return res.sendStatus(404);
  const row = toApi(found, req);
  const avail = LANGS.filter((l) => row.versions[l.code]);
  const pref = (req.get("accept-language") || "").split(",").map((s) => s.split(";")[0].trim().toLowerCase().split("-")[0]);
  const start = (avail.find((l) => l.code === req.query.lang) || pref.map((p) => avail.find((l) => l.code === p)).find(Boolean) || avail[0]).code;
  const title = row.titles[start] || row.titles[Object.keys(row.titles)[0]] || "Video";
  const prefCode = pref.find((p) => isLang(p)) || "";
  const labels = Object.fromEntries(LANGS.map((l) => [l.code, l.label]));
  const data = JSON.stringify({ start, pref: prefCode, labels, langs: avail, versions: row.versions }).replace(/</g, "\\u003c");
  res.type("html").send(`<!doctype html><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>${esc(title)}</title>
<style>
html,body{margin:0;height:100%;background:#000;font-family:system-ui,sans-serif}
body{display:flex;flex-direction:column}
#bar{display:flex;gap:6px;padding:8px;justify-content:flex-end}
#bar button{border:1px solid #555;background:#111;color:#fff;border-radius:999px;padding:4px 12px;font:600 13px system-ui;cursor:pointer}
#bar button[aria-pressed=true]{background:#fff;color:#000}
video{flex:1;min-height:0;width:100%;object-fit:contain;background:#000}
</style>
<div id="bar"></div>
<video id="v" controls playsinline preload="none"></video>
<script>
var D=${data},v=document.getElementById("v"),bar=document.getElementById("bar");
function set(code,keep){
  var t=v.currentTime,play=!v.paused,x=D.versions[code];
  [].slice.call(v.querySelectorAll("track")).forEach(function(n){n.remove()});
  var subs=x.subs||[];if(subs.length)v.crossOrigin="anonymous";else v.removeAttribute("crossorigin");
  subs.forEach(function(s){var n=document.createElement("track");n.kind="subtitles";n.src=s.url;n.srclang=s.lang;n.label=D.labels[s.lang]||s.lang;if(s.lang===D.pref&&s.lang!==code)n.default=true;v.appendChild(n)});
  v.poster=x.poster||"";v.src=x.video;
  if(keep){v.addEventListener("loadedmetadata",function f(){v.removeEventListener("loadedmetadata",f);v.currentTime=t;if(play)v.play()});v.load()}
  [].forEach.call(bar.children,function(b){b.setAttribute("aria-pressed",b.dataset.c===code)});
}
if(D.langs.length>1)D.langs.forEach(function(l){var b=document.createElement("button");b.textContent=l.label;b.dataset.c=l.code;b.onclick=function(){set(l.code,true)};bar.appendChild(b)});
set(D.start,false);
</script>`);
});

process.on("unhandledRejection", (e) => console.error("Unhandled:", e));

loadDb().then(() => {
  const server = app.listen(PORT, "0.0.0.0", () => {
    console.log(`Listening on port ${PORT}`);
    console.log(R2 ? `Storage: Cloudflare R2 / S3 bucket "${BUCKET}"` : `Storage: local disk at ${DATA_DIR} (attach a Railway Volume to this path so files survive redeploys)`);
    console.log(`Languages: ${LANGS.map((l) => l.code).join(", ")}`);
  });
  server.requestTimeout = 0;      // long uploads must not be cut off
  server.keepAliveTimeout = 65000;
}).catch((e) => { console.error("Could not load the database:", e); process.exit(1); });

