<script>
const $ = (id) => document.getElementById(id);
const VID = [".mp4", ".m4v", ".mov", ".webm"], IMG = [".jpg", ".jpeg", ".png", ".webp"], SUB = [".vtt", ".srt"];
const BIG = 100e6; // files above this go through multipart upload
const ext = (n) => (n.match(/\\.[^.]+$/) || [""])[0].toLowerCase();
const stem = (n) => n.replace(/\\.[^.]+$/, "");
const gb = (b) => (b >= 1e9 ? (b / 1e9).toFixed(1) + " GB" : Math.max(1, Math.round(b / 1e6)) + " MB");
const natural = (a, b) => a.name.localeCompare(b.name, undefined, { numeric: true, sensitivity: "base" });
const el = (tag, cls, text) => { const e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; };

let cfg = [], videos = [], sel = {}, plan = [], busy = false, limit = Infinity;
const limitTxt = () => \`\${+(limit / 1024 ** 3).toFixed(2)} GB\`;
$("key").value = sessionStorage.getItem("uk") || "";

const baseOf = (name) => stem(name).replace(new RegExp("[\\\\s._-]+(" + cfg.map((l) => l.code).join("|") + ")$", "i"), "");
const norm = (s) => s.toLowerCase().replace(/[^\\p{L}\\p{N}]+/gu, "");
const pretty = (s) => s.replace(/[._]+/g, " ").replace(/\\s+/g, " ").trim();
const anyOf = (m) => { for (const l of cfg) if (m && m[l.code]) return m[l.code]; return ""; };
const say = (t, cls) => { $("msg").className = "msg " + (cls || ""); $("msg").textContent = t; };

/* ---------- selecting folders, files and ZIP archives ---------- */
const MIME = { ".mp4": "video/mp4", ".m4v": "video/x-m4v", ".mov": "video/quicktime", ".webm": "video/webm", ".jpg": "image/jpeg", ".jpeg": "image/jpeg", ".png": "image/png", ".webp": "image/webp" };

function buildLangs() {
  const box = $("langs"); box.textContent = "";
  cfg.forEach((l) => {
    sel[l.code] = { videos: [], images: [], subs: [], row: "" };
    const fs = el("fieldset"); fs.appendChild(el("legend", "", \`\${l.label} (\${l.code.toUpperCase()})\`));
    const row = el("label", "", "Row name (optional)"); const ri = el("input"); ri.type = "text"; ri.id = "row_" + l.code; ri.placeholder = "Defaults to each folder's name";
    ri.addEventListener("input", () => {
      sel[l.code].row = ri.value;
      if (busy) return;
      plan.forEach((e) => { const it = e.per[l.code]; if (it && it.file) it.row = ri.value.trim() || it.group || it.container || ""; });
      renderPlan();
    });
    row.appendChild(ri);
    const mk = (kind) => {
      const i = el("input"); i.type = "file"; i.multiple = true; i.hidden = true;
      if (kind === "dir") i.webkitdirectory = true;
      else if (kind === "zip") i.accept = ".zip,application/zip,application/x-zip-compressed";
      else i.accept = "video/*,image/*,.srt,.vtt";
      i.addEventListener("change", () => {
        const fl = [...i.files]; i.value = "";
        if (kind === "zip") (async () => { for (const z of fl) await addZip(l.code, z); })(); else addFiles(l.code, fl);
      });
      return i;
    };
    const dirIn = mk("dir"), fileIn = mk("files"), zipIn = mk("zip");
    const btn = (label, input) => { const b = el("button", "ghost", label); b.type = "button"; b.onclick = () => input.click(); return b; };
    const sum = el("p", "sum", "Nothing selected"); sum.id = "sum_" + l.code;
    const br = el("div", "btnrow"); br.append(btn("Choose folder", dirIn), btn("Choose files", fileIn), btn("Choose ZIP", zipIn));
    fs.append(row, br, sum, dirIn, fileIn, zipIn); box.appendChild(fs);
  });
}
function updateSummary(code) {
  const s = sel[code], total = s.videos.reduce((n, f) => n + f.size, 0);
  const named = new Set(s.videos.filter((f) => f._g).map((f) => f._g)).size;
  const parts = [];
  if (s.videos.length) parts.push(\`\${s.videos.length} video\${s.videos.length > 1 ? "s" : ""} · \${gb(total)}\`);
  if (named) parts.push(\`\${named} series folder\${named > 1 ? "s" : ""}\`);
  if (s.images.length) parts.push(\`\${s.images.length} image\${s.images.length > 1 ? "s" : ""}\`);
  if (s.subs.length) parts.push(\`\${s.subs.length} subtitle\${s.subs.length > 1 ? "s" : ""}\`);
  $("sum_" + code).textContent = parts.join(" · ") || "Nothing selected";
}
// every file knows its container (the picked folder / ZIP) and its group (the sub-folder = series)
function annotate(f) {
  if (f._g !== undefined) return f;
  const p = (f.webkitRelativePath || "").split("/").filter(Boolean);
  if (p.length >= 2) { f._c = p[0]; f._g = p.length > 2 ? p[1] : ""; } else { f._c = ""; f._g = ""; }
  return f;
}
function addFiles(code, list) {
  if (busy) return;
  const s = sel[code];
  for (const raw of list) {
    const f = annotate(raw), e = ext(f.name);
    const bucket = VID.includes(e) ? s.videos : IMG.includes(e) ? s.images : SUB.includes(e) ? s.subs : null;
    if (!bucket) continue;
    if (!bucket.some((x) => x.name === f.name && x.size === f.size && x._g === f._g)) bucket.push(f);
  }
  s.videos.sort(natural);
  updateSummary(code);
  buildPlan();
}

/* zip-start */
async function readZip(file) {
  const size = file.size;
  if (size < 22) throw new Error("This is not a valid ZIP file.");
  const tailLen = Math.min(size, 65535 + 22 + 20);
  const tail = new DataView(await file.slice(size - tailLen, size).arrayBuffer());
  let eocd = -1;
  for (let i = tail.byteLength - 22; i >= 0; i--) if (tail.getUint32(i, true) === 0x06054b50) { eocd = i; break; }
  if (eocd < 0) throw new Error("This is not a valid ZIP file.");
  let count = tail.getUint16(eocd + 10, true), cdSize = tail.getUint32(eocd + 12, true), cdOff = tail.getUint32(eocd + 16, true);
  if (count === 0xffff || cdSize === 0xffffffff || cdOff === 0xffffffff) {
    const loc = eocd - 20;
    if (loc < 0 || tail.getUint32(loc, true) !== 0x07064b50) throw new Error("Unsupported ZIP64 layout.");
    const z64 = Number(tail.getBigUint64(loc + 8, true));
    const z = new DataView(await file.slice(z64, z64 + 56).arrayBuffer());
    if (z.getUint32(0, true) !== 0x06064b50) throw new Error("Damaged ZIP64 header.");
    count = Number(z.getBigUint64(32, true)); cdSize = Number(z.getBigUint64(40, true)); cdOff = Number(z.getBigUint64(48, true));
  }
  const buf = await file.slice(cdOff, cdOff + cdSize).arrayBuffer();
  const cd = new DataView(buf), bytes = new Uint8Array(buf);
  const out = [];
  let p = 0;
  for (let n = 0; n < count; n++) {
    if (p + 46 > cd.byteLength || cd.getUint32(p, true) !== 0x02014b50) throw new Error("Damaged ZIP directory.");
    const flags = cd.getUint16(p + 8, true), method = cd.getUint16(p + 10, true);
    let csize = cd.getUint32(p + 20, true), usize = cd.getUint32(p + 24, true), lho = cd.getUint32(p + 42, true);
    const nlen = cd.getUint16(p + 28, true), elen = cd.getUint16(p + 30, true), clen = cd.getUint16(p + 32, true);
    const nb = bytes.subarray(p + 46, p + 46 + nlen);
    let name = new TextDecoder("utf-8").decode(nb);
    if (name.includes("\\ufffd")) name = new TextDecoder("windows-1252").decode(nb);
    let q = p + 46 + nlen; const qe = q + elen;
    while (q + 4 <= qe) {
      const id = cd.getUint16(q, true), sz = cd.getUint16(q + 2, true);
      if (id === 1) {
        let o = q + 4;
        if (usize === 0xffffffff) { usize = Number(cd.getBigUint64(o, true)); o += 8; }
        if (csize === 0xffffffff) { csize = Number(cd.getBigUint64(o, true)); o += 8; }
        if (lho === 0xffffffff) { lho = Number(cd.getBigUint64(o, true)); }
      }
      q += 4 + sz;
    }
    out.push({ name: name.replace(/\\\\/g, "/"), flags, method, csize, usize, lho });
    p += 46 + nlen + elen + clen;
  }
  return out;
}
async function zipEntryFile(zf, e, name) {
  if (e.flags & 1) throw new Error("This ZIP is password-protected, which is not supported.");
  const lh = new DataView(await zf.slice(e.lho, e.lho + 30).arrayBuffer());
  if (lh.getUint32(0, true) !== 0x04034b50) throw new Error("Damaged ZIP entry: " + e.name);
  const start = e.lho + 30 + lh.getUint16(26, true) + lh.getUint16(28, true);
  const raw = zf.slice(start, start + e.csize);
  let blob;
  if (e.method === 0) blob = raw;
  else if (e.method === 8) {
    if (typeof DecompressionStream === "undefined") throw new Error("This browser cannot unpack compressed ZIP files. Use a current Chrome, Edge, Safari or Firefox, or create the ZIP without compression.");
    blob = await new Response(raw.stream().pipeThrough(new DecompressionStream("deflate-raw"))).blob();
  } else throw new Error("Unsupported ZIP compression in " + e.name + ". Re-create the ZIP with standard (Deflate) or no compression.");
  return new File([blob], name, { type: MIME[ext(name)] || "" });
}
/* zip-end */

async function addZip(code, zf) {
  if (busy) return;
  const sum = $("sum_" + code);
  try {
    sum.textContent = "Reading ZIP…";
    const ents = (await readZip(zf)).filter((e) => !e.name.endsWith("/") && !e.name.split("/").some((s) => s === "__MACOSX" || s.startsWith(".")));
    const wanted = ents.filter((e) => VID.includes(ext(e.name)) || IMG.includes(ext(e.name)) || SUB.includes(ext(e.name)));
    if (!wanted.length) throw new Error("No videos, images or subtitles found in " + zf.name + ".");
    const tops = new Set(ents.map((e) => e.name.split("/")[0]));
    const strip = tops.size === 1 && ents.every((e) => e.name.includes("/"));
    const container = strip ? [...tops][0] : stem(zf.name);
    const files = [];
    for (const [i, e] of wanted.entries()) {
      sum.textContent = \`Reading ZIP… \${i + 1}/\${wanted.length}\`;
      const parts = e.name.split("/"), rest = strip ? parts.slice(1) : parts;
      const f = await zipEntryFile(zf, e, rest[rest.length - 1]);
      f._c = container; f._g = rest.length > 1 ? rest[0] : "";
      files.push(f);
    }
    addFiles(code, files);
  } catch (err) {
    updateSummary(code); say(err.message || "Could not read the ZIP file.", "err");
  }
}

/* ---------- pairing plan ---------- */
const subInfo = (name, folderCode) => {
  const s = stem(name), m = s.match(new RegExp("^(.*?)[\\\\s._-]+(" + cfg.map((l) => l.code).join("|") + ")$", "i"));
  return m ? { base: m[1], lang: m[2].toLowerCase() } : { base: s, lang: folderCode };
};
let planNote = "";
const fsize = (it) => (it.file ? it.file.size : 0);

// Posters inside one folder: same name first; then ONE leftover image = series poster; then pair leftovers in order
const SERIES_NAMES = new Set(["poster", "cover", "series", "folder", "show", "row"]);
function planPosters(o) {
  const byName = {};
  o.images.forEach((f) => { byName[norm(baseOf(f.name))] = f; });
  let series = o.images.find((f) => { const b = norm(baseOf(f.name)); return SERIES_NAMES.has(b) || (o.name && b === norm(o.name)); }) || null;
  const map = new Map(), free = [];
  o.videos.forEach((v) => { const m = byName[norm(baseOf(v.name))]; if (m && m !== series) map.set(v, m); else free.push(v); });
  const used = new Set(map.values());
  const left = o.images.filter((i) => !used.has(i) && i !== series);
  if (free.length && !series) {
    if (left.length === 1) series = left[0];
    else if (left.length === free.length) free.forEach((v, i) => map.set(v, left[i]));
  }
  return { map, series };
}
function groupsOf(code) {
  const g = new Map();
  const get = (f) => {
    const k = f._g || "";
    if (!g.has(k)) g.set(k, { name: k, container: f._c || "", videos: [], images: [], subs: [] });
    const o = g.get(k); if (!o.container && f._c) o.container = f._c; return o;
  };
  sel[code].videos.forEach((f) => get(f).videos.push(f));
  sel[code].images.forEach((f) => get(f).images.push(f));
  sel[code].subs.forEach((f) => get(f).subs.push(f));
  g.forEach((o) => {
    o.videos.sort(natural); o.images.sort(natural);
    o.pm = planPosters(o);
    o.subsMap = {};
    o.subs.forEach((f) => { const { base, lang } = subInfo(f.name, code); (o.subsMap[norm(base)] = o.subsMap[norm(base)] || {})[lang] = f; });
  });
  return g;
}

function buildPlan() {
  const mode = document.querySelector("input[name=mode]:checked").value;
  const G = {}; cfg.forEach((l) => { G[l.code] = groupsOf(l.code); });
  const cmpName = (a, b) => a.localeCompare(b, undefined, { numeric: true, sensitivity: "base" });
  const rowFor = (code, o) => (sel[code].row || "").trim() || o.name || o.container || "";
  const item = (code, o, f) => ({
    file: f, base: baseOf(f.name), group: o.name, container: o.container,
    poster: o.pm.map.get(f) || o.pm.series || null, rowPoster: o.pm.series,
    subs: o.subsMap[norm(baseOf(f.name))] || {}, row: rowFor(code, o),
  });
  const first = (e) => cfg.map((l) => e.per[l.code]).find(Boolean);
  let entries = [];
  if (mode === "name") {
    const map = new Map();
    cfg.forEach((l) => [...G[l.code].values()].sort((a, b) => cmpName(a.name, b.name)).forEach((o) => o.videos.forEach((f) => {
      const k = norm(o.name) + "|" + norm(baseOf(f.name));
      if (!map.has(k)) map.set(k, { per: {}, titles: {} });
      if (!map.get(k).per[l.code]) map.get(k).per[l.code] = item(l.code, o, f);
    })));
    entries = [...map.values()].sort((a, b) => cmpName(first(a).group + " / " + first(a).base, first(b).group + " / " + first(b).base));
  } else {
    const lists = {};
    cfg.forEach((l) => { lists[l.code] = [...G[l.code].values()].filter((o) => o.videos.length).sort((a, b) => cmpName(a.name, b.name)); });
