  document.head.appendChild(css);

  function el(tag, cls, text) {
    var e = document.createElement(tag);
    if (cls) e.className = cls;
    if (text) e.textContent = text;
    return e;
  }

  var languages = [], videos = [], lang = "";

  function firstOf(map) { // value in the visitor's language, else the first configured language that has one
    if (!map) return "";
    if (map[lang]) return map[lang];
    for (var i = 0; i < languages.length; i++) if (map[languages[i].code]) return map[languages[i].code];
    return "";
  }
  function versionFor(entry, code) {
    if (entry.versions[code]) return entry.versions[code];
    for (var i = 0; i < languages.length; i++) if (entry.versions[languages[i].code]) return entry.versions[languages[i].code];
  }
  function pickInitialLang() {
    var codes = languages.map(function (l) { return l.code; });
    var want = (script.dataset.lang || "").toLowerCase();
    if (codes.indexOf(want) > -1) return want;
    var prefs = navigator.languages || [navigator.language || ""];
    for (var i = 0; i < prefs.length; i++) {
      var p = prefs[i].toLowerCase();
      if (codes.indexOf(p) > -1) return p;
      if (codes.indexOf(p.split("-")[0]) > -1) return p.split("-")[0];
    }
    return codes[0];
  }

  function applySubs(video, v, audioCode) {
    Array.prototype.slice.call(video.querySelectorAll("track")).forEach(function (t) { t.remove(); });
    var subs = v.subs || [];
    if (subs.length) video.crossOrigin = "anonymous"; else video.removeAttribute("crossorigin");
    subs.forEach(function (s) {
      var t = document.createElement("track");
      t.kind = "subtitles"; t.src = s.url; t.srclang = s.lang;
      var L = languages.filter(function (l) { return l.code === s.lang; })[0];
      t.label = L ? L.label : s.lang;
      if (s.lang === lang && s.lang !== audioCode) t.default = true;
      video.appendChild(t);
    });
  }

  function openPlayer(entry, opener) {
    var avail = languages.filter(function (l) { return entry.versions[l.code]; });
    var current = entry.versions[lang] ? lang : avail[0].code;
    var title = firstOf(entry.titles);

    var modal = el("div", "nf-modal");
    modal.setAttribute("role", "dialog"); modal.setAttribute("aria-modal", "true"); modal.setAttribute("aria-label", title);
    var dlg = el("div", "nf-dialog");
    var video = document.createElement("video");
    video.controls = true; video.autoplay = true; video.playsInline = true;
    var close = el("button", "nf-close", "\\u00d7");
    close.setAttribute("aria-label", "Close");
    var foot = el("div", "nf-foot");
    foot.appendChild(el("h4", "", title));
    var pills = el("div", "nf-langs"); pills.style.margin = "0";

    function setLang(code, keep) {
      var v = entry.versions[code], t = video.currentTime, playing = !video.paused;
      video.poster = v.poster || "";
      applySubs(video, v, code);
      video.src = v.video;
      if (keep) {
        video.addEventListener("loadedmetadata", function f() {
          video.removeEventListener("loadedmetadata", f);
          video.currentTime = t;
          if (playing) video.play();
        });
        video.load();
      }
      Array.prototype.forEach.call(pills.children, function (b) { b.setAttribute("aria-pressed", String(b.dataset.c === code)); });
    }
    if (avail.length > 1) {
      avail.forEach(function (l) {
        var b = el("button", "nf-pill", l.label);
        b.type = "button"; b.dataset.c = l.code;
        b.addEventListener("click", function () { setLang(l.code, true); });
        pills.appendChild(b);
      });
      foot.appendChild(pills);
    }
    dlg.appendChild(close); dlg.appendChild(video); dlg.appendChild(foot);
    modal.appendChild(dlg);
    document.body.appendChild(modal);
    var prevOverflow = document.body.style.overflow;
    document.body.style.overflow = "hidden";
    setLang(current, false);
    close.focus();

    function done() {
      video.pause(); video.removeAttribute("src"); video.load();
      modal.remove();
      document.body.style.overflow = prevOverflow;
      document.removeEventListener("keydown", onKey);
      if (opener) opener.focus();
