    function onKey(e) { if (e.key === "Escape") done(); }
    document.addEventListener("keydown", onKey);
    close.addEventListener("click", done);
    modal.addEventListener("click", function (e) { if (e.target === modal) done(); });
  }

  function card(entry) {
    var title = firstOf(entry.titles);
    var b = el("button", "nf-card");
    b.type = "button";
    b.setAttribute("aria-label", "Play " + title);
    var v = versionFor(entry, lang);
    if (v && v.poster) {
      var img = document.createElement("img");
      img.src = v.poster; img.alt = ""; img.loading = "lazy";
      b.appendChild(img);
    } else {
      b.appendChild(el("div", "nf-noposter"));
    }
    var fade = el("div", "nf-fade");
    fade.appendChild(el("div", "nf-play"));
    fade.appendChild(el("div", "nf-title", title));
    var codes = languages.filter(function (l) { return entry.versions[l.code]; }).map(function (l) { return l.code.toUpperCase(); });
    if (codes.length > 1) fade.appendChild(el("div", "nf-badges", codes.join(" \\u00b7 ")));
    b.appendChild(fade);
    b.addEventListener("click", function () { openPlayer(entry, b); });
    return b;
  }

  function row(name, items, cover) {
    var sec = el("section", "nf-row");
    if (cover) {
      var hd = el("div", "nf-rowhead"), im = document.createElement("img");
      im.className = "nf-rowcover"; im.src = cover; im.alt = ""; im.loading = "lazy";
      hd.appendChild(im); hd.appendChild(el("h3", "nf-head", name)); sec.appendChild(hd);
    } else sec.appendChild(el("h3", "nf-head", name));
    var wrap = el("div", "nf-wrap");
    var sc = el("div", "nf-scroller");
    items.forEach(function (e) { sc.appendChild(card(e)); });
    var prev = el("button", "nf-arrow nf-prev", "\\u2039");
    var next = el("button", "nf-arrow nf-next", "\\u203a");
    prev.type = next.type = "button";
    prev.setAttribute("aria-label", "Scroll left in " + name);
    next.setAttribute("aria-label", "Scroll right in " + name);
    prev.addEventListener("click", function () { sc.scrollBy({ left: -sc.clientWidth * 0.85, behavior: "smooth" }); });
    next.addEventListener("click", function () { sc.scrollBy({ left: sc.clientWidth * 0.85, behavior: "smooth" }); });
    wrap.appendChild(prev); wrap.appendChild(sc); wrap.appendChild(next);
    sec.appendChild(wrap);
    return sec;
  }

  function render() {
    var root = el("div", "nf");
    if (languages.length > 1) {
      var bar = el("div", "nf-langs");
      languages.forEach(function (l) {
        var p = el("button", "nf-pill", l.label);
        p.type = "button";
        p.setAttribute("aria-pressed", String(l.code === lang));
        p.addEventListener("click", function () { lang = l.code; render(); });
        bar.appendChild(p);
      });
      root.appendChild(bar);
    }
    var list = limit ? videos.slice(0, limit) : videos;
    var groups = {}, order = [];
    list.forEach(function (e) { // rows are grouped by the default-language row name
      var key = e.categories[languages[0].code] || firstOfCode(e.categories) || "Videos";
      if (!groups[key]) { groups[key] = []; order.push(key); }
      groups[key].push(e);
    });
    order.forEach(function (key) {
      var name = key;
      groups[key].some(function (e) { if (e.categories[lang]) { name = e.categories[lang]; return true; } });
      var cover = "";
      groups[key].some(function (e) {
        var rp = e.rowPosters && (e.rowPosters[lang] || firstOfCode(e.rowPosters));
        if (rp) { cover = rp; return true; }
      });
      root.appendChild(row(name, groups[key], cover));
    });
    target.textContent = "";
    target.appendChild(root);
  }
  function firstOfCode(map) {
    for (var i = 0; i < languages.length; i++) if (map[languages[i].code]) return map[languages[i].code];
  }

  fetch(origin + "/api/videos")
    .then(function (r) { return r.json(); })
    .then(function (data) {
      languages = data.languages; videos = data.videos;
      lang = pickInitialLang();
      render();
    })
    .catch(function () { target.textContent = "Videos could not be loaded."; });
})();
